const { v2Header, v2Footer, socialIconCells, websiteLabel, PEKO_SOCIAL_LINKS } = require('./emailTemplate/sharedLayout');
const { otpBlockHtml } = require('./emailTemplate/signUp');

// key: OTP_VERIFICATION (service: AUTH)
// MFA-on-login code, sent from configs/local_auth.js when an existing user has
// email-delivered MFA enabled. Not to be confused with SIGNUP_OTP, which verifies a
// brand new user before an account exists.
exports.commonEmailOtpVerification = ({ otp, name, partnerDetails }) => {
  const website = partnerDetails?.baseUrl || 'https://in.peko.one';
  const branding = partnerDetails?.branding || 'Peko';
  const logo = partnerDetails?.logo;

  const headerHtml = v2Header({ website, websiteLabel: websiteLabel(website), logo, branding });
  const footerHtml = v2Footer({ socials: socialIconCells(PEKO_SOCIAL_LINKS, { size: 24, padding: '0 16px' }), branding });

  return `<!doctype html>
  <html lang="en" dir="ltr" xmlns="http://www.w3.org/1999/xhtml" xmlns:v="urn:schemas-microsoft-com:vml" xmlns:o="urn:schemas-microsoft-com:office:office">
    <head>
      <title>Multi-Factor Authentication Code for Login</title>
      <meta http-equiv="Content-Type" content="text/html; charset=UTF-8">
      <meta name="viewport" content="width=device-width, initial-scale=1">
    </head>
    <body style="word-spacing:normal;background-color:#F9FAFB;margin:0;padding:0;">
      <div aria-label="Multi-Factor Authentication Code for Login" aria-roledescription="email" style="background-color:#F9FAFB;" role="article" lang="en" dir="ltr">
${headerHtml}
        <div style="background:#F9FAFB;margin:0 auto;max-width:680px;padding:0 20px;">
          <div style="background-color:#ffffff;border-radius:16px;padding:48px;font-family:'Segoe UI','Helvetica Neue',Arial,sans-serif;">
            <h2 style="margin:0 0 24px 0;font-size:28px;font-weight:700;color:#000000;">Multi-Factor Authentication Code for Login</h2>
            <p style="font-size:16px;line-height:1.6;color:#000000;margin:0 0 20px 0;">Dear ${name},</p>
            <p style="font-size:16px;line-height:1.6;color:#000000;margin:0 0 20px 0;">Below is your Multi-Factor Authentication Code for Login. This code is valid for 2 minutes only.</p>
            ${otpBlockHtml(otp)}
            <p style="font-size:16px;line-height:1.6;color:#000000;margin:0;">Best Regards,<br/>Team ${branding}</p>
          </div>
        </div>
${footerHtml}
      </div>
    </body>
  </html>`;
};

